// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Ensure the target is not the contract itself and is not payable
        vm.assume(target != address(0));
        vm.assume(target != address(c));
        value = bound(value, 1, 100 ether);
        // Fund the contract so it can send
        vm.deal(address(c), value);
        // Try to send money to a contract that does not have a receive function
        bool success;
        try c.sendMoney(target, value) {
            success = true;
        } catch {
            success = false;
        }
        // The reference (low-level call) succeeds even to non-payable targets
        // The mutation (transfer) reverts because transfer to a contract without receive fails
        // So the rule: sendMoney should succeed (the reference behavior)
        assertTrue(success);
    }
}

